{
    let status = 0, failed = false, terminal: TerminalPort | undefined, dialog: Dialog | undefined;
    let state: ClientLocalStateInstance | undefined, client: GovernanceClientOperations | undefined, use: GovernanceUse | undefined;
    let closing: Promise<void> | undefined, dialogClosing: Promise<void> | undefined;
    let origin: Origin = { centerId: null, accountId: null, loginStateHandle: null }, tenant: Tenant | undefined;
    let source = 'unknown', lastReport: ActionReport | undefined, lastShown = false;
    const controller = new AbortController();
    const diagnostics = new Set<Diagnostic>();
    const close = () => {
        controller.abort();
        if (dialog && !dialogClosing) {
            dialogClosing = dialog.stop();
            void dialogClosing.catch(() => { });
        }
        if (client && !closing) {
            try {
                closing = client.close();
            }
            catch {
                closing = Promise.reject(new Error('client close failed'));
            }
            void closing.catch(() => { });
        }
    };
    const identity = () => dialog?.identity([
        `Center: ${origin.centerId ?? 'unknown'}`,
        `Account: ${origin.accountId ?? 'unknown'}`,
        `Organization: ${tenant?.organization ?? 'unknown / unconfirmed'}`,
        `Identity source: ${source}`,
    ]);
    runtime.signal.addEventListener('abort', close);
    try {
        await (async () => {
            const options = tuiOptions(args, runtime.home);
            if (options === 'help') {
                await runtime.stdout('Usage: omne tui --terminal-profile <profile> [--state-dir <absolute directory>] [--setup]\nProfiles: xterm-379 (XTerm 379, allowPasteControls=false); iterm-3.7.1beta1 (macOS only).\nRequires UTF-8, a direct exclusive TTY, ordinary keys and plain-text clipboard paste.\niTerm: no special paste, file URLs, auto-composer, broadcast, tmux, paste cancellation or keystroke passthrough; finish IME composition before pasting.\nNoSyncTurnOffBracketedPasteOnHostChange must not be true; never accept Yes/Always to disable bracketing during use.\nSetup: configure, health, register or login; one action, then reopen. Credentials come from protected files. The entire UTF-8 file, including any final newline, is used without trimming; preserve its contents for later login.\nTerminal acceptance remains incomplete; these profiles state required conditions, not environment detection. Use omne machine for redirected output.\n');
                return 0;
            }
            if (runtime.signal.aborted)
                throw new InputFailure('input-cancelled');
            terminal = await runtime.terminal(options.profile);
            dialog = new Dialog(terminal, close);
            if (controller.signal.aborted)
                throw new InputFailure('input-cancelled');
            state = await runtime.openState({ directory: options.directory });
            if (controller.signal.aborted)
                throw new InputFailure('input-cancelled');
            client = runtime.createClient({ state });
            if (!options.setup) {
                const opened = await client.openUse();
                if (controller.signal.aborted)
                    throw new InputFailure('input-cancelled');
                if (opened.kind === 'use') {
                    use = opened.use;
                    origin = opened.origin;
                }
                else if (opened.kind !== 'blocked')
                    throw new Error('invalid openUse result');
                else if (opened.reason === 'local-unavailable') {
                    status = 3;
                    throw new InputFailure('state-unavailable');
                }
                else if (opened.reason === 'invalid-record' || opened.reason === 'unsupported-format')
                    throw new InputFailure('state-invalid');
                else if (opened.reason !== 'not-configured' && opened.reason !== 'not-logged-in')
                    throw new Error('unexpected admission');
            }
            identity();
            const activeDialog = dialog, activeClient = client;
            const execute = async (form: Form, prepared: PreparedForm, userRequested: boolean): Promise<boolean> => {
                const runner = use ?? activeClient;
                const report = await runner.runPrepared(prepared.intent, async (preview, signal) => {
                    const cancelled = () => close();
                    signal.addEventListener('abort', cancelled);
                    try {
                        if (signal.aborted || controller.signal.aborted)
                            return { kind: 'cancelled' };
                        origin = preview.origin;
                        identity();
                        const proceed = readForm(form)
                            ? await activeDialog.show('Preview: ' + form.label, previewBody(preview), true)
                            : (await activeDialog.choose('Confirm: ' + form.label, ['Cancel', 'Confirm this operation'], previewBody(preview))) === 1;
                        if (!proceed || signal.aborted)
                            return { kind: 'cancelled' };
                        try {
                            return await formSecrets(prepared.secretPaths, signal);
                        }
                        catch (error) {
                            if (error instanceof InputFailure) {
                                diagnostics.add(error.code);
                                return { kind: 'cancelled' };
                            }
                            throw error;
                        }
                    }
                    finally {
                        signal.removeEventListener('abort', cancelled);
                    }
                });
